    selected_case := 'CASE_STUDENT';

    FOR s IN (
      SELECT s0."StuID", s0."LName"
      FROM "Student" s0
      WHERE s0."StuID" BETWEEN (arg4 - 5) AND (arg4 + 15)
    ) LOOP
      row_count := row_count + 1;

      IF s."LName" = arg5 THEN
        UPDATE "Student"
        SET "Major" = 700
        WHERE "StuID" = s."StuID";
      END IF;

      IF s."LName" LIKE 'ACTIVE%' THEN
        UPDATE "Student"
        SET "LName" = 'PROCESSED'
        WHERE "StuID" = s."StuID";
      ELSIF s."StuID" > (arg4 + 5) THEN
        threshold := threshold + s."StuID";
      ELSE
        DELETE FROM "Student"
        WHERE "StuID" = s."StuID"
          AND "LName" = 'EXPIRED';
      END IF;

      IF row_count >= batch_size THEN
        batch_size := batch_size + 5;
      END IF;
    END LOOP;

  ELSIF threshold < 18 THEN
    selected_case := 'CASE_RESTYPE';

    FOR t IN (
      SELECT t0."ResTypeID"
      FROM "Restaurant_Type" t0
      WHERE t0."ResTypeID" > (arg6 - 20)
    ) LOOP
      row_count := row_count + 1;

      IF t."ResTypeID" < 50 THEN
        status_text := 'LOW_PRIORITY';
      ELSIF t."ResTypeID" < 150 THEN
        status_text := 'MEDIUM_PRIORITY';
      ELSE
        status_text := 'HIGH_PRIORITY';
      END IF;

      UPDATE "Restaurant_Type"
      SET "ResTypeID" = "ResTypeID" + 10
      WHERE "ResTypeID" = t."ResTypeID";

      UPDATE "Type_Of_Restaurant"
      SET "ResTypeID" = "ResTypeID" + 10
      WHERE "ResTypeID" = t."ResTypeID";

      IF row_count >= batch_size THEN
        batch_size := batch_size + 5;
      END IF;
    END LOOP;

  ELSIF threshold < 25 THEN
    selected_case := 'CASE_ARCHIVE';

    UPDATE "Restaurant"
    SET "Address" = 'ARCHIVED'
    WHERE "ResID" < arg1
      AND "ResName" <> arg2;

